// ═══ WRONG: swallowing InterruptedException ═══
while (running) {
    try {
        String trade = queue.take();  // blocks — interruptible!
        settle(trade);
    } catch (InterruptedException e) {
        // SWALLOWED! Interrupt flag CLEARED!
        // queue.take() in next iteration blocks FOREVER
        // shutdownNow() can't stop this thread!
        // Thread runs until JVM is killed!
    }
}

// ═══ CORRECT 1: restore interrupt flag ═══
while (!Thread.currentThread().isInterrupted()) {  // check flag!
    try {
        String trade = queue.take();
        settle(trade);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();  // RESTORE flag!
        // Next loop iteration: isInterrupted() returns true → exits loop!
        // Or: queue.take() will throw InterruptedException again immediately!
    }
}

// ═══ CORRECT 2: rethrow (propagate to caller) ═══
public void processSettlements() throws InterruptedException {
    while (true) {
        String trade = queue.take();  // might throw InterruptedException
        settle(trade);
        // If interrupted: exception propagates to caller — caller decides what to do
    }
}

// ═══ WHY the flag is cleared on catch ═══
// Thread.interrupt() → sets interrupt flag to true
// Thread is in sleep/wait/take → InterruptedException thrown
// Catching InterruptedException → flag automatically CLEARED to false!
// This is by design — the exception IS the notification.
// But if you catch and ignore: both the exception AND flag are gone!

// ═══ HOW shutdownNow() uses interrupts ═══
pool.shutdownNow();
// 1. Sets pool state to STOP
// 2. Calls thread.interrupt() on ALL worker threads
// 3. Workers in blocking calls → InterruptedException
// 4. If worker restores flag → next blocking call throws again → exit!
// 5. If worker SWALLOWS → blocking call continues → thread NEVER stops!

// ═══ CORRECT PATTERNS ═══
// Pattern 1: Service method (restore + exit)
while (!Thread.currentThread().isInterrupted()) {
    try { doBlockingWork(); }
    catch (InterruptedException e) {
        Thread.currentThread().interrupt();  // restore!
        break;  // exit gracefully
    }
}
cleanup();

// Pattern 2: Library method (rethrow — let caller decide)
public Trade fetchNext() throws InterruptedException {
    return queue.take();  // propagate to caller
}

// Pattern 3: Runnable in pool (restore flag)
Runnable task = () -> {
    try { doWork(); }
    catch (InterruptedException e) {
        Thread.currentThread().interrupt();  // restore for pool!
        return;
    }
};
