package com.bank.interrupt;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class InterruptHandlingTest {

    // ═══ WRONG: swallow interrupt → thread never stops ═══
    @Test
    void swallow_threadNeverStops() throws InterruptedException {
        AtomicBoolean stopped = new AtomicBoolean(false);

        Thread swallower = new Thread(() -> {
            while (true) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    // SWALLOWED! Flag cleared! Loop continues forever!
                }
            }
        });
        swallower.start();
        swallower.interrupt();  // try to stop!
        swallower.join(500);    // wait 500ms

        assertThat(swallower.isAlive()).isTrue();  // STILL RUNNING! Can't stop!
        swallower.interrupt();  // try again — still swallowed!
        swallower.stop();  // desperate! (deprecated, unsafe!)
    }

    // ═══ CORRECT: restore flag → thread exits ═══
    @Test
    void restoreFlag_threadExitsGracefully() throws InterruptedException {
        AtomicBoolean cleanedUp = new AtomicBoolean(false);

        Thread worker = new Thread(() -> {
            while (!Thread.currentThread().isInterrupted()) {
                try {
                    Thread.sleep(100);
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();  // RESTORE!
                    // Next iteration: isInterrupted() = true → loop exits!
                }
            }
            cleanedUp.set(true);  // cleanup runs!
        });
        worker.start();
        Thread.sleep(200);

        worker.interrupt();  // signal stop
        worker.join(2000);

        assertThat(worker.isAlive()).isFalse();    // stopped!
        assertThat(cleanedUp.get()).isTrue();       // cleanup ran!
    }

    // ═══ shutdownNow + proper interrupt handling ═══
    @Test
    void shutdownNow_worksWithRestoredFlag() throws InterruptedException {
        ExecutorService pool = Executors.newFixedThreadPool(3);
        AtomicInteger completed = new AtomicInteger(0);
        CountDownLatch started = new CountDownLatch(3);

        for (int i = 0; i < 3; i++) {
            pool.submit(() -> {
                started.countDown();
                while (!Thread.currentThread().isInterrupted()) {
                    try {
                        Thread.sleep(50);
                        completed.incrementAndGet();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();  // restore!
                    }
                }
            });
        }
        started.await();
        Thread.sleep(200);

        pool.shutdownNow();  // interrupts all workers!
        boolean terminated = pool.awaitTermination(5, TimeUnit.SECONDS);

        assertThat(terminated).isTrue();  // all stopped!
        assertThat(completed.get()).isGreaterThan(0);
    }

    // ═══ interrupt flag behavior ═══
    @Test
    void interruptFlag_clearedOnCatch() {
        Thread t = Thread.currentThread();

        t.interrupt();
        assertThat(t.isInterrupted()).isTrue();  // flag set!

        try {
            Thread.sleep(1);  // throws because flag is set!
        } catch (InterruptedException e) {
            assertThat(t.isInterrupted()).isFalse();  // flag CLEARED by catch!
            t.interrupt();  // RESTORE!
            assertThat(t.isInterrupted()).isTrue();   // flag restored!
        }

        Thread.interrupted();  // clear for test cleanup
    }
}
